"""Make a review copy without changing the supplied manuscript or its results tables."""
from pathlib import Path
import difflib
import hashlib
import json
import re

ROOT = Path(__file__).resolve().parents[1]
source = ROOT / "main.tex"
original_bytes = source.read_bytes()
assert hashlib.sha256(original_bytes).hexdigest() == "aa30a5ec6f4ff99a7756fd00213af29789fa35b132c53832c3b7705636dcd402", "The source changed after review; inspect it before regenerating this copy."
original = original_bytes.decode("utf-8").replace("\r\n", "\n")
lines = original.splitlines()
changes = []


def paragraph(line, replacement, reason):
    old = lines[line - 1]
    assert old.strip() and not old.lstrip().startswith("%"), (line, old)
    lines[line - 1] = replacement
    changes.append({"original_line": line, "reason": reason, "before": old, "after": replacement})


paragraph(424, r"""We examined how inlet diameter and sac asymmetry affect flow in twelve idealized \DTAA geometries, then used their \CFD fields to test pressure and \WSS recovery from sparse velocity. Nine aneurysmal models combined three inlet diameters (2.0, 2.3 and 2.6~cm) with axisymmetric, anterior-dominant and posterior-dominant sacs; three models served as controls. All aneurysms had a maximum diameter of 4.0~cm, and all vessels had an outlet-to-inlet diameter ratio of 0.8. At a fixed flow waveform, narrowing the inlet from 2.6 to 2.0~cm increased systolic pressure drop from 528--561 to 1261--1346~Pa and the 95th-percentile \WSS from 7--8 to 15--18~Pa. Asymmetry mainly changed the location of low shear and increased diastolic segment-median \WSS by a factor of 1.8--3.1 relative to axisymmetric sacs. Reconstruction used noise-free velocity sampled at about 1.3\% of interior nodes at two instants 5--10~ms apart. Interpolation and space-time neural fields were compared using shared pressure and shear calculations. In seven evaluation geometries, the continuity-constrained field reduced pressure and \WSS errors relative to the prespecified \RBF in all 14 case--phase means, with median error ratios of 0.46 and 0.51. Most of the benefit came from the neural representation; momentum-constrained \PINNs tested on two development geometries did not improve joint pressure and shear recovery. Diastolic pressure estimates depended on \CFD-supplied eddy viscosity, and \WSS accuracy deteriorated when near-wall observations were removed. These results characterize reconstruction in known, idealized geometries; they do not establish performance on measured data or clinical rupture risk.""", "Shorten abstract; keep task, main estimates, negative result and practical limits.")
paragraph(434, r"""Descending thoracic aortic aneurysms alter both blood flow and the mechanical loading of the vessel wall. Their geometry varies in parent-vessel size, curvature and sac asymmetry. These features can differ even when two aneurysms have the same maximum diameter, motivating comparisons that control diameter while varying the surrounding geometry~\cite{lipp2020computational,vorp1998mechanical}.""", "Replace textbook anatomy with the specific research problem.")
paragraph(436, r"""Maximum diameter is an important clinical measure, but it does not describe wall thickness, tissue properties or the full aneurysm shape. Evidence from abdominal aortic aneurysms shows that diameter alone does not determine rupture~\cite{darling1977autopsy} and has motivated complementary volumetric measures~\cite{kitagawa2013role}. These observations motivate biomechanical analysis, but findings from abdominal or cerebral aneurysms cannot by themselves establish rupture predictors for \DTAA. Structural tensile stress and hemodynamic \WSS also describe different loads: local wall failure depends on the relation between tissue stress and tissue strength, whereas \WSS characterizes tangential loading by blood flow~\cite{vorp1998mechanical,bilgi2020effects}.""", "Remove outdated prevalence and unsupported universal 5 cm rule; distinguish WSS from tissue stress and anatomical evidence.")
paragraph(438, r"""\CFDcap estimates velocity, pressure and shear fields that are difficult to measure throughout an aneurysm~\cite{lee2011computational,morris2016computational}. Common descriptors include \WSS, \WSSG, \TAWSS and \OSI. Their associations with disease depend on the anatomy and outcome studied. Geers et al.~\cite{geers2017wall}, for example, examined shear at cerebral aneurysm initiation sites, whereas Moon et al.~\cite{moon2025hemodynamic} reported low \TAWSS and elevated oscillatory and residence-time indices at rupture regions in four infrarenal aneurysms. Such findings motivate spatial hemodynamic comparisons without establishing a validated rupture model for the idealized thoracic geometries studied here.""", "Replace causal clinical claims with anatomy-specific evidence.")
paragraph(440, r"""Parent-vessel diameter and curvature affect the jet entering an aneurysm and the resulting recirculation. Studies of tortuous arteries have linked these geometric features to changes in shear and residence-time indices~\cite{10a,11a,12a,13a,14a}. In intracranial aneurysm models, larger parent-vessel diameters reduced \WSS and \OSI~\cite{fattahi2023influence,fattahi2023usage}, while changes in aspect and size ratios altered near-neck hemodynamics~\cite{nagargoje2022influence}. A controlled thoracic-aorta model allows these geometric effects to be examined without the simultaneous anatomical variation present in patient cohorts.""", "Reduce literature-list repetition and avoid unsupported rupture implications.")
paragraph(442, r"""Pulsatility, curvature and sac expansion can produce transitional flow, making the choice of flow model relevant to the calculated hemodynamics~\cite{brambila2023influence,evju2015assumption,luciano2024turbulent,rawat2019numerical}. Reynolds-averaged turbulence models represent the effects of unresolved fluctuations through a closure; \DNS instead resolves the turbulent scales directly. Here we use the transition \SST $k$--$\omega$ model to represent possible laminar--turbulent transition. The resulting turbulence quantities are model predictions and require validation before being interpreted as measurements of physiological turbulence.""", "Correct DNS classification and replace blanket claims of turbulence-model necessity.")
paragraph(446, r"""The present study examines a curved, tapered family of twelve idealized descending thoracic aortas (Table~\ref{tab:lit_review}). Nine aneurysmal geometries combine inlet diameters of 2.0, 2.3 and 2.6~cm with axisymmetric, anterior-dominant and posterior-dominant sacs; three nonaneurysmal geometries provide matched controls. The maximum sac diameter is fixed at 4.0~cm, and every vessel has an outlet-to-inlet diameter ratio of 0.8. This design compares inlet diameter and bulge direction under a common taper and flow waveform. Because taper is fixed, the study does not estimate the effect of changing taper itself.""", "State the actual controlled comparison; fixed taper is not an experimentally isolated effect.")
paragraph(448, r"""The same \CFD fields support a second question: how accurately can pressure and \WSS be recovered from sparse velocity in a known geometry? Time-resolved three-dimensional phase-contrast MRI (4D flow MRI) samples velocity on voxels of roughly one to three millimeters~\cite{markl2012fourd}; pressure and wall shear must be estimated from those measurements. Relative-pressure methods use the momentum balance~\cite{krittian2012finite,bertoglio2018relative}, while velocity-derived \WSS is sensitive to resolution and wall segmentation~\cite{stalder2008quantitative,petersson2012assessment,potters2015volumetric}. Neural fields provide a continuous velocity representation, optionally constrained by the governing equations~\cite{raissi2019pinn,raissi2020hfm}. Applications include arterial pressure inference~\cite{kissas2020machine}, 4D flow reconstruction~\cite{fathi2020super,saitta2024implicit}, near-wall flow recovery~\cite{arzani2021nearwall} and aneurysm flow reconstruction~\cite{cruzgonzalez2025aaa}. Their performance depends on the observations, training procedure and comparator~\cite{krishnapriyan2021failure,wang2021gradient,mcgreivy2024weak}.""", "Remove an untested surrogate-speed motivation and focus on reconstruction.")
paragraph(450, r"""We separate the benefit of the neural representation from that of the physics terms in its loss. We also test which additional inputs pressure and shear recovery require. In unsteady Reynolds-averaged flow, the pressure gradient depends on acceleration and the eddy-viscosity closure as well as velocity. All methods therefore use the same sampled observation pool and shared pressure and shear calculations, with closure information reported explicitly. Table~\ref{tab:lit_review} places this comparison alongside earlier idealized-aneurysm studies.""", "Make the methodological question direct without an unverified broad novelty claim.")
paragraph(498, r"""The geometry study supplies reference flows with different jet strengths, recirculation patterns and modeled eddy viscosities. The reconstruction study tests recovery across those conditions. Each reconstruction receives observations in its target geometry; it does not predict flow in an anatomy without observations or estimate clinical rupture risk.""", "Remove conversational justification and state the relation between study components.")
paragraph(668, r"""A no-slip condition was imposed at the wall.""", "Correct grammar.")
paragraph(682, r"""The cycle-averaged magnitude of \WSS was computed on the aneurysm wall~\cite{morbiducci2010outflow,turk2021characterization}:""", "Only TAWSS follows; remove the claim that two directional metrics were computed.")
paragraph(688, r"""\TKEcap per unit mass, $k=\tfrac12\overline{v_i'v_i'}$, was used to summarize the modeled velocity fluctuations in the sac. It is a scalar quantity with units of m$^2$~s$^{-2}$, rather than the fluctuating velocity components themselves.""", "Correct the TKE definition.")
paragraph(690, r"""Speed and \TKE were also summarized at eight cross-sectional planes (D1--D8) to compare their variation along the vessel with local diameter.""", "Remove grammar errors and repetitive wording.")
paragraph(693, r"""\MPScap was evaluated on the inner wall surface to describe tensile loading in the structural model. It is the largest principal value of the local stress tensor. Elevated \MPS identifies modeled stress concentrations; predicting failure would additionally require local tissue-strength data, which were not available.""", "Keep structural results distinct from failure prediction.")
paragraph(723, lines[722].replace("results from the third cardiac cycle were used for all subsequent analyses.", "snapshots from the third cardiac cycle were used for the instantaneous flow comparisons. The exact averaging cycle of the retained \\TAWSS export requires separate confirmation."), "Do not extend the verified snapshot cycle to an undocumented TAWSS averaging window.")
paragraph(727, r"""\subsubsection{Pressure-loaded structural model}""", "Use a heading supported by the retained pressure-transfer workflow.")
paragraph(736, r"""Both ends of the structural domain were fixed. Fluid pressure was transferred to the inner wall surface in ANSYS Mechanical (Figure~\ref{fig:Flowchart}). All quantitative flow and reconstruction results use the rigid-wall fluid solution (Section~\ref{sec:exports}). The retained coupling records are insufficient to establish a bidirectional moving-wall calculation; the structural results are therefore interpreted as pressure-loaded wall-stress fields.""", "Resolve contradictory wording conservatively; do not invent a verified two-way FSI procedure.")
paragraph(864, lines[863].replace("A random 10\\% of the observed nodes is withheld from fitting and used only for model selection and monitoring.", "The neural fields withhold a random 10\\% of sampled nodes from fitting for model selection and monitoring. The fixed interpolation comparators use all sampled observations; the tuned comparators use the holdout for selection and then refit using all observations. Thus the sampled observation pool is shared, but the final fitting subsets differ."), "Describe the actual 90% neural / 100% interpolation fitting allocation found in the code.")
paragraph(871, lines[870].replace("99.5th percentile of observed speed", "99.5th percentile of training-observation speed"), "Match the scaling definition in training.py.")
paragraph(991, lines[990].replace("indicating that the isotropic turbulent stress is already contained in the exported pressure.", "which is consistent with an effective-pressure convention but does not, by itself, verify the solver's exported pressure definition."), "Separate an empirical residual check from proof of the pressure convention.")
paragraph(997, lines[996].replace("which is widened to 128 sources only where a neighborhood is coplanar and the local system is singular", "with fallback neighborhoods of 128 and then 256 sources if the local system is singular"), "Match the RBF fallback implemented in interpolation.py.")
paragraph(1196, lines[1195].replace("Because every method passes through that post-processing, this choice favors none of them.", "The same choices are applied to every method. However, because the evaluation-case targets informed these choices, the seven-case evaluation is independent of reconstruction tuning rather than of the entire analysis pipeline."), "A common postprocessor does not establish independence from evaluation-target-informed design.")
paragraph(1202, r"""The geometry comparisons use nine aneurysmal models and three matched controls, grouped by inlet diameter (Table~\ref{tab:geometries}). We report streamlines, pressure drop, reversed-flow fraction, \WSS, \TAWSS and structural \MPS. Instantaneous flow quantities use the common systolic and diastolic times defined in Section~\ref{sec:exports}. The structural fields represent systolic pressure loading; \TAWSS is a cycle average, whose exact averaging cycle requires confirmation from the solver record.""", "Remove the contradiction between third-cycle and final-cycle analyses; flag missing TAWSS provenance.")
paragraph(1206, r"""Figures~\ref{fig:streamlines_2p0}--\ref{fig:streamlines_2p6} show recirculation in the aneurysm sacs and at the inner curvature of the proximal descending aorta. At the bend, the flow shifts toward the outer curvature, leaving a low-momentum region along the inner wall where separation occurs; we refer to this as the \ICRZ (Figure~\ref{fig:diagram}). Within the sacs, the recirculation pattern changes with bulge direction and is pronounced in the anterior-dominant geometries. The transverse views show secondary vortices on both sides of the sac. The controls have smoother streamlines apart from the bend-associated recirculation. These patterns are consistent with prolonged residence in parts of the sac, but thrombus formation and tissue weakening were not simulated~\cite{salman2019biomechanical}.""", "Replace repetitive flow description and causal speculation with observed patterns.")
paragraph(1254, lines[1253].replace("illustrates the 2D graphics of", "shows the signed axial component of").replace("Figure~\\ref{fig:xwss}(a) represents", "Panel~(a) shows").replace("Figure~\\ref{fig:xwss}(b) shows", "panel~(b) shows").replace("Figure~\\ref{fig:xwss}(c) presents", "Panel~(c) shows"), "Identify the signed shear component rather than describing a negative magnitude.")
paragraph(1259, r"""\caption{Axial component of \WSS (Pa) along wall intersections with the medial and transverse planes at systole: (a) anterior medial wall, (b) posterior medial wall and (c) transverse-plane wall intersection.}""", "Clarify what can take negative values; confirm the component against the plotting script.")
paragraph(1266, lines[1265].replace("The analysis of \\TAWSS, as presented in Figure~\\ref{fig:tawss} and Table~\\ref{tab:tawss}, across twelve idealized geometries revealed several consistent trends.", "Figure~\\ref{fig:tawss} and Table~\\ref{tab:tawss} summarize \\TAWSS across the twelve geometries.").replace("Increasing the inlet diameter from 2~cm to 2.6~cm was associated with a progressive reduction in \\TAWSS.", "The aneurysmal segment medians generally rise from the 2.0~cm group to the larger-diameter groups; the 95th percentiles and control medians decrease with inlet diameter. These statistics therefore describe different trends."), "Correct the TAWSS trend using the supplied table; distinguish medians from upper percentiles.")
paragraph(1268, lines[1267].replace("the lowest \\TAWSS is consistently placed", "the lowest \\TAWSS is usually located").replace("It is also observed that the bulge side is where the instantaneous shear is lowest at systole, so that the dominant bulge is exposed to low shear over the whole cycle rather than at a single instant. This reinforces the need for a multi-parametric hemodynamic assessment that includes both \\WSS and \\TAWSS to identify rupture-prone \\DTAAs.", "The bulge also has low instantaneous shear at systole. Together, these results show low systolic and low cycle-averaged shear; they do not establish that shear remains low at every instant or identify rupture-prone tissue."), "Respect the Case 3 exception and avoid whole-cycle and clinical inference from limited summaries.")
paragraph(1284, r"""The structural calculation tests how pressure loading is distributed across the prescribed wall geometry. Diameter and asymmetry can alter tissue stress~\cite{vorp1998mechanical}, but stress alone does not determine failure because local wall strength is unknown. A Laplace-law estimate based on a uniform cylinder does not capture the changing curvature at an aneurysm's necks and crown; the three-dimensional structural model is used here to describe those stress concentrations.""", "Remove generic opening and avoid extrapolating abdominal rupture observations to thoracic risk.")
paragraph(1286, lines[1285].replace("A clear distinction was observed between axisymmetric and asymmetric cases.", "The two morphology groups differ in their sac-body stress distribution.").replace("equal to within 1~kPa", "within 1.2~kPa of each other").replace("The opposite-side value increases with inlet diameter, as does the segment median of the controls (52.5, 58.4 and 65.1~kPa), because the loaded radius grows with the parent vessel.", "Median sac-body \\MPS on the wall opposite the dominant bulge increases with inlet diameter. The controls show the same trend in segment-median \\MPS (52.5, 58.4 and 65.1~kPa for inlet diameters of 2.0, 2.3 and 2.6~cm, respectively). This trend is consistent with greater tensile loading at a larger vessel radius under comparable pressure and wall thickness."), "Name stress statistics, correct the axisymmetric difference to 1.2 kPa, and qualify the radius-based explanation.")
paragraph(1288, r"""The controls have relatively uniform wall stress, with 95th percentiles within 3~kPa of their medians and mild elevations near the bend. In the asymmetric sacs, the wall opposite the dominant bulge has the higher sac-body median. Case~9 has the highest anterior sac-body median, 80.3~kPa; this is not a claim about the largest local peak. Indeed, the highest reported neck 95th percentile is 113.4~kPa in Case~5 (Table~\ref{tab:mps}). These are modeled loading patterns, obtained with a uniform 2~mm wall, literature material parameters and fixed ends. The retained records do not include the coupling-step settings, and local tissue strength is unknown, so the stress fields do not identify a failure site or quantify rupture risk.""", "Correct the Case 9 statistic and remove unsupported rupture ranking.")
paragraph(1304, r"""Plane-wise speed and \TKE summaries describe how the flow changes along the vessel and where the sac-associated disturbance persists downstream.""", "Remove generic framing.")
paragraph(1306, r"""The eight planes are shown in Figure~\ref{fig:diagram}, and their diameters are listed in Table~\ref{tab:diameter}. Figure~\ref{fig:planes} shows the retained plane summaries for every case; Table~\ref{tab:plane_cfd} gives group medians. Speed is higher at D7--D8 than at D1--D3, consistent with the narrower distal lumen~\cite{kahveci2015numerical}. In the aneurysmal cases it falls to 0.10--0.16~m~s$^{-1}$ at D5, where every sac reaches 4.0~cm, compared with a control median of 0.193~m~s$^{-1}$, and recovers by D7. Continuity constrains cross-sectional mean axial velocity through flow rate and area; the plotted mean speed also reflects recirculation and the averaging used in the retained summaries. These prescribed-flow models do not test downstream perfusion.""", "Remove untested claims about adequate perfusion and distinguish mean speed from mean axial velocity.")
paragraph(1308, r"""Modeled $k$ rises through the sac, reaches about twice the control value at D5, remains elevated at D6--D7 and returns toward the control level at D8. The asymmetric sacs have higher D5 values than the axisymmetric sacs at each inlet diameter. These profiles are consistent with the sac recirculation and distal reattachment seen in the streamline maps~\cite{yu2000steady}. They locate the modeled disturbance but do not directly resolve the underlying turbulent fluctuations.""", "Avoid repetitive or stronger-than-supported causal descriptions of modeled turbulence.")
paragraph(1310, r"""The plane summaries place the largest speed reduction at the sac center and the elevated modeled \TKE across the sac and its downstream region. They complement the wall quantities by describing the flow within the lumen. Because the slice workbook does not retain its averaging interval, these profiles are treated as descriptive summaries rather than independently verified cycle averages (Section~\ref{Limitations}).""", "Replace repetitive conclusion and state the averaging provenance limitation at point of use.")
paragraph(1333, lines[1332].replace("and the 1\\% difference in the residual scaling does not affect the conclusions drawn from them.", "The difference is about 1\\%, but its effect on optimization was not tested by retraining."), "A small density change does not prove unchanged training outcomes.")
paragraph(1343, re.sub(r"For reference, a two-sided sign test.*?not independent\. ", "The draw-level counts are descriptive because draws and phases share geometries; they are not treated as independent replicates for significance testing. ", lines[1342]), "Remove an invalid independent-draw p-value while keeping all reported win counts.")
paragraph(1446, lines[1445].replace("The comparison against the prespecified \\RBF is therefore not an artifact of a weak interpolant, although a stronger interpolant narrows the diastolic pressure gap.", "The advantage persists against the two additional interpolants tested, although they narrow the diastolic pressure gap. This does not exclude other interpolation schemes from performing better."), "Limit robustness conclusions to the tested alternatives.")
paragraph(1465, lines[1464].replace("and shifted the distal high-shear region toward it, ", ""), "Remove a direction claim that conflicts with the results paragraph's anterior distal-neck pattern.")
paragraph(1493, lines[1492].replace("Twelve idealized descending thoracic aortic geometries with a fixed maximum sac diameter of 4.0~cm were simulated", "Twelve idealized descending thoracic aortic geometries, comprising nine aneurysmal models with a fixed maximum sac diameter of 4.0~cm and three nonaneurysmal controls, were simulated"), "Avoid implying that the controls have a 4 cm sac.")
paragraph(1495, lines[1494].replace("diastolic pressure required the \\CFD eddy viscosity as an input to the oracle", "diastolic pressure errors increased when the \\CFD-supplied eddy viscosity was omitted"), "Express the tested ablation result without implying a universal closure requirement.")

# Local comments preserve open methodological questions without inventing settings.
notes = {
    734: "% AUTHOR CHECK: confirm material constants by group, prestress/reference state, external pressure and solid-mesh convergence.",
    698: "% AUTHOR CHECK: non-monotonic refinement and assumed p=2 do not establish an asymptotic convergence regime; add transient/multi-endpoint checks.",
    991: "% AUTHOR CHECK: verify the exported Fluent/CFD-Post pressure definition and isotropic turbulent-stress convention from the solver setup.",
    1202: "% AUTHOR CHECK: identify the exact TAWSS integration cycle and time window from retained solver records.",
    1509: "% AUTHOR CHECK: the existing AI-use declaration remains commented. Apply the target journal's policy and describe actual use accurately.",
}
revised = "\n".join((notes.get(i, "") + "\n" if i in notes else "") + line for i, line in enumerate(lines, 1)) + "\n"
output = ROOT / "main_revised.tex"
output.write_text(revised, encoding="utf-8")
(ROOT / "review" / "editorial_changes.json").write_text(json.dumps(changes, indent=2), encoding="utf-8")
diff = "".join(difflib.unified_diff(original.splitlines(True), revised.splitlines(True), fromfile="main.tex", tofile="main_revised.tex"))
(ROOT / "review" / "manuscript_changes.diff").write_text(diff, encoding="utf-8")
assert source.read_bytes() == original_bytes
print(json.dumps({"revised_file": str(output), "revised_paragraphs_or_lines": len(changes), "original_sha256": hashlib.sha256(original_bytes).hexdigest(), "original_preserved": True}))
